antine_event_id":"02741cc2-afbf-4094-845e-57bf377c2fd4"}]$manifest$::jsonb;
 item jsonb;
 original local_labor_requirement_events%ROWTYPE;
 requirement_stream local_labor_requirement_streams%ROWTYPE;
 failure constant text := 'Không thể tạm ngưng mẫu kỹ thuật: dữ liệu không còn ở trạng thái cài đặt mới. Cần kiểm tra chỉ đọc và bảo trì riêng.';
BEGIN
 IF (SELECT count(*) FROM local_labor_requirement_streams)<>10 OR (SELECT count(*) FROM local_labor_requirement_events)<>10
 OR EXISTS(SELECT 1 FROM local_product_supply_classifications)
 OR EXISTS(SELECT 1 FROM local_product_supply_receipts)
 OR EXISTS(SELECT 1 FROM local_product_technical_versions)
 OR EXISTS(SELECT 1 FROM local_product_technical_receipts)
 OR EXISTS(SELECT 1 FROM local_labor_mapping_decisions)
 OR EXISTS(SELECT 1 FROM local_labor_mapping_versions)
 OR EXISTS(SELECT 1 FROM local_labor_mapping_receipts)
 OR EXISTS(SELECT 1 FROM local_labor_requirement_proposals)
 OR EXISTS(SELECT 1 FROM local_labor_requirement_drafts)
 OR EXISTS(SELECT 1 FROM local_labor_requirement_receipts)
 OR EXISTS(SELECT 1 FROM local_product_rate_action_receipts)
 THEN RAISE EXCEPTION USING MESSAGE=failure; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP
  SELECT * INTO requirement_stream FROM local_labor_requirement_streams WHERE id=(item->>'stream_id')::uuid;
  IF NOT FOUND OR requirement_stream.code_key IS DISTINCT FROM item->>'code_key'
   OR requirement_stream.created_by IS DISTINCT FROM 'REVIEWED_SEED'
   OR requirement_stream.created_at IS NULL OR NOT isfinite(requirement_stream.created_at)
  THEN RAISE EXCEPTION USING MESSAGE=failure; END IF;
  SELECT * INTO original FROM local_labor_requirement_events WHERE stream_id=requirement_stream.id AND version=1;
  IF NOT FOUND OR original.id IS NULL OR original.created_at IS NULL OR NOT isfinite(original.created_at)
   OR original.action IS DISTINCT FROM 'APPROVE' OR original.effective_from IS DISTINCT FROM DATE '0001-01-01' OR original.effective_to IS NOT NULL
   OR original.semantic_fingerprint IS DISTINCT FROM item->>'semantic_fingerprint'
   OR original.definition IS DISTINCT FROM item->'definition' OR original.content_hash IS DISTINCT FROM item->>'content_hash'
   OR original.author_id IS DISTINCT FROM 'REVIEWED_SEED' OR original.reviewer_id IS DISTINCT FROM 'REVIEWED_SEED'
   OR original.reason IS DISTINCT FROM 'Nhập đúng mười hợp đồng đã được rà soát'
   OR original.legacy_id IS DISTINCT FROM item->>'legacy_id' OR original.legacy_version IS DISTINCT FROM item->>'legacy_version'
   OR original.seed_manifest_hash IS DISTINCT FROM 'a658a5b160be41cdc928a3bcf0a725f5583827c8e7f6c813868928ed0352d2a1'
   OR original.proposal_id IS NOT NULL OR original.proposal_revision IS NOT NULL
   OR EXISTS(SELECT 1 FROM local_labor_requirement_events WHERE id=(item->>'quarantine_event_id')::uuid)
  THEN RAISE EXCEPTION USING MESSAGE=failure; END IF;
 END LOOP;
 -- All gates finish before the first append. No conflict suppression or version inference.
 FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP
  SELECT * INTO STRICT original FROM local_labor_requirement_events WHERE stream_id=(item->>'stream_id')::uuid AND version=1;
  INSERT INTO local_labor_requirement_events(id,stream_id,version,action,effective_from,effective_to,semantic_fingerprint,definition,content_hash,proposal_id,proposal_revision,author_id,reviewer_id,reason,legacy_id,legacy_version,seed_manifest_hash)
  VALUES((item->>'quarantine_event_id')::uuid,original.stream_id,2,'RETIRE',DATE '0001-01-01',NULL,original.semantic_fingerprint,original.definition,original.content_hash,NULL,NULL,
   'SYSTEM_INSTALL_QUARANTINE','SYSTEM_INSTALL_QUARANTINE','Tạm ngưng mẫu kỹ thuật do cài đặt: chưa xác nhận phê duyệt nghiệp vụ của người có trách nhiệm; chờ cấu hình và duyệt theo quy trình.',original.legacy_id,original.legacy_version,original.seed_manifest_hash);
 END LOOP;
END;
$quarantine$;
